//! Plays the bundled reminder timbres and the optional focus tick. The app
//! never posts operating-system notifications; sound is the only boundary cue.

use std::fs::{self, File};
use std::io::{BufReader, Cursor};
use std::path::{Path, PathBuf};
use std::sync::mpsc::{self, RecvTimeoutError, SyncSender};
use std::sync::{Mutex, OnceLock};
use std::time::Duration;

use log::warn;
use rodio::{Decoder, Sink, Source};

use crate::settings::SoundPreset;

/// Every clip is generated by `scripts/generate-sound-pack.mjs` and embedded,
/// so playback does not depend on the operating system sound scheme.
static CHIME: &[u8] = include_bytes!("../assets/notification.wav");
static SOFT: &[u8] = include_bytes!("../assets/notification-soft.wav");
static BELL: &[u8] = include_bytes!("../assets/notification-bell.wav");
static TICK: &[u8] = include_bytes!("../assets/tick.wav");

const START_TIMEOUT: Duration = Duration::from_secs(2);
const MAX_CUSTOM_BYTES: u64 = 2 * 1024 * 1024;
const MAX_CUSTOM_DURATION: Duration = Duration::from_secs(5);

enum Clip {
    Bytes(&'static [u8]),
    File(PathBuf),
}

impl Clip {
    fn open(&self) -> Result<Box<dyn rodio::Source<Item = f32> + Send>, String> {
        match self {
            Self::Bytes(bytes) => Ok(Box::new(
                Decoder::new(Cursor::new(*bytes)).map_err(|error| error.to_string())?,
            )),
            Self::File(path) => {
                let file = File::open(path).map_err(|error| error.to_string())?;
                Ok(Box::new(
                    Decoder::new(BufReader::new(file)).map_err(|error| error.to_string())?,
                ))
            }
        }
    }
}

/// Plays a reminder and waits until the audio device accepted it. Used by the
/// settings preview, where a real error is better than a silent failure.
pub fn play(preset: SoundPreset, volume: u8, custom_path: Option<&str>) -> Result<(), String> {
    let Some(clip) = clip_for(preset, custom_path) else {
        return Ok(());
    };
    start(clip, volume, true)
}

/// Starts a reminder without waiting. Used when a session ends so the timer
/// thread never blocks on audio initialization.
pub fn play_in_background(preset: SoundPreset, volume: u8, custom_path: Option<&str>) {
    let Some(clip) = clip_for(preset, custom_path) else {
        return;
    };
    if let Err(error) = start(clip, volume, false) {
        warn!("failed to start reminder sound: {error}");
    }
}

/// Sends one quiet tick while a focus session runs. The audio stream is kept
/// alive for 30 seconds after the last tick, then released.
pub fn tick() {
    let mut guard = tick_sender()
        .lock()
        .unwrap_or_else(|poison| poison.into_inner());
    if guard.is_none() {
        *guard = spawn_tick_thread();
    }
    let sent = guard
        .as_ref()
        .is_some_and(|sender| sender.try_send(()).is_ok());
    if !sent {
        *guard = spawn_tick_thread();
        if let Some(sender) = guard.as_ref() {
            let _ = sender.try_send(());
        }
    }
}

/// Validates a user-selected clip and copies it into the app data directory.
/// The original file can then move or disappear without breaking playback.
pub fn import_custom(app: &tauri::AppHandle, source: &Path) -> Result<String, String> {
    use tauri::Manager;

    let metadata = fs::metadata(source).map_err(|error| error.to_string())?;
    if metadata.len() > MAX_CUSTOM_BYTES {
        return Err("sound.tooLarge".to_owned());
    }
    let file = File::open(source).map_err(|error| error.to_string())?;
    let decoder = Decoder::new(BufReader::new(file)).map_err(|_| "sound.unreadable".to_owned())?;
    let duration = decoder
        .total_duration()
        .ok_or_else(|| "sound.unreadable".to_owned())?;
    if duration > MAX_CUSTOM_DURATION {
        return Err("sound.tooLong".to_owned());
    }
    let extension = source
        .extension()
        .and_then(|value| value.to_str())
        .unwrap_or("wav")
        .to_ascii_lowercase();
    let directory = app
        .path()
        .app_data_dir()
        .map_err(|error| error.to_string())?
        .join("sounds");
    fs::create_dir_all(&directory).map_err(|error| error.to_string())?;
    let target = directory.join(format!("{}.{}", uuid::Uuid::now_v7(), extension));
    fs::copy(source, &target).map_err(|error| error.to_string())?;
    Ok(target.display().to_string())
}

fn clip_for(preset: SoundPreset, custom_path: Option<&str>) -> Option<Clip> {
    match preset {
        SoundPreset::Chime => Some(Clip::Bytes(CHIME)),
        SoundPreset::Soft => Some(Clip::Bytes(SOFT)),
        SoundPreset::Bell => Some(Clip::Bytes(BELL)),
        SoundPreset::Custom => custom_path
            .filter(|path| !path.trim().is_empty())
            .map(|path| Clip::File(PathBuf::from(path))),
        SoundPreset::Off => None,
    }
}

fn start(clip: Clip, volume: u8, wait: bool) -> Result<(), String> {
    let (ready, receiver) = mpsc::sync_channel(1);
    let gain = gain_for(volume);
    std::thread::Builder::new()
        .name("reminder-sound".to_owned())
        .spawn(move || play_blocking(ready, clip, gain))
        .map_err(|error| error.to_string())?;
    if !wait {
        return Ok(());
    }
    match receiver.recv_timeout(START_TIMEOUT) {
        Ok(result) => result,
        Err(RecvTimeoutError::Timeout) => Err("the audio device did not respond".to_owned()),
        Err(RecvTimeoutError::Disconnected) => Err("the audio device is unavailable".to_owned()),
    }
}

fn play_blocking(ready: SyncSender<Result<(), String>>, clip: Clip, gain: f32) {
    let source = match clip.open() {
        Ok(source) => source,
        Err(error) => {
            let _ = ready.send(Err(error.clone()));
            warn!("failed to decode reminder sound: {error}");
            return;
        }
    };
    match rodio::OutputStreamBuilder::open_default_stream() {
        Ok(stream) => {
            let sink = Sink::connect_new(stream.mixer());
            sink.set_volume(gain);
            sink.append(source);
            let _ = ready.send(Ok(()));
            sink.sleep_until_end();
            drop(stream);
        }
        Err(error) => {
            let message = error.to_string();
            let _ = ready.send(Err(message.clone()));
            warn!("failed to play reminder sound: {message}");
        }
    }
}

/// A squared curve keeps low volume settings genuinely quiet instead of
/// jumping to half loudness as a linear mapping would.
fn gain_for(volume: u8) -> f32 {
    let value = f32::from(volume.min(100)) / 100.0;
    value * value
}

fn tick_sender() -> &'static Mutex<Option<SyncSender<()>>> {
    static SENDER: OnceLock<Mutex<Option<SyncSender<()>>>> = OnceLock::new();
    SENDER.get_or_init(|| Mutex::new(None))
}

fn spawn_tick_thread() -> Option<SyncSender<()>> {
    let (sender, receiver) = mpsc::sync_channel(1);
    std::thread::Builder::new()
        .name("focus-tick".to_owned())
        .spawn(move || {
            let Ok(stream) = rodio::OutputStreamBuilder::open_default_stream() else {
                return;
            };
            let sink = Sink::connect_new(stream.mixer());
            sink.set_volume(gain_for(30));
            while let Ok(()) = receiver.recv_timeout(Duration::from_secs(30)) {
                let Ok(source) = Decoder::new(Cursor::new(TICK)) else {
                    continue;
                };
                sink.append(source);
                sink.sleep_until_end();
            }
        })
        .ok()?;
    Some(sender)
}

#[cfg(test)]
mod tests {
    use super::*;
    use rodio::Source;

    fn duration(bytes: &'static [u8]) -> Duration {
        Decoder::new(Cursor::new(bytes))
            .expect("clip decodes")
            .total_duration()
            .expect("clip has a duration")
    }

    #[test]
    fn every_bundled_clip_decodes_with_a_usable_duration() {
        assert!(duration(CHIME) >= Duration::from_millis(900));
        assert!(duration(SOFT) >= Duration::from_millis(900));
        assert!(duration(BELL) >= Duration::from_millis(800));
        assert!(duration(TICK) >= Duration::from_millis(40));
        assert!(duration(TICK) <= Duration::from_millis(120));
    }

    #[test]
    fn the_volume_curve_is_squared_and_bounded() {
        assert_eq!(gain_for(0), 0.0);
        assert_eq!(gain_for(100), 1.0);
        assert!((gain_for(50) - 0.25).abs() < f32::EPSILON);
        assert_eq!(gain_for(200), 1.0);
    }
}
